from concurrent.futures import ThreadPoolExecutor

def check(n):
    if n == 3:
        raise ValueError(f"bad input {n}")
    return n * n

with ThreadPoolExecutor(max_workers=2) as pool:
    futures = [pool.submit(check, n) for n in range(1, 5)]
    for n, future in zip(range(1, 5), futures):
        try:
            print(n, "->", future.result())
        except ValueError as error:
            print(n, "-> error:", error)
EOF
